{
  "hypotheses": [
    {
      "id": "H1",
      "signal": "momentum",
      "lookback": 1,
      "citation": "jegadeesh-titman-1993",
      "hypothesis": "Assets with the highest return over the last completed interval keep outperforming the rest over the next interval.",
      "mechanism": "Delayed reaction to information makes recent cross-sectional winners continue to lead.",
      "assumptions": [
        "The reaction delay is long enough to show up between daily marks.",
        "Ranking a small universe still separates winners from losers."
      ],
      "limitations": [
        "The cited evidence is monthly; a one-interval lookback is a loose analogue.",
        "No cost, capacity or significance test is part of the rule."
      ]
    },
    {
      "id": "H2",
      "signal": "reversal",
      "lookback": 1,
      "citation": "jegadeesh-1990",
      "hypothesis": "Assets with the lowest return over the last completed interval outperform over the next interval.",
      "mechanism": "Short-horizon overreaction and liquidity pressure partly unwind in the following interval.",
      "assumptions": [
        "Overreaction at daily marks behaves like the monthly effect in the note."
      ],
      "limitations": [
        "Reversal profits are known to be cost-sensitive; the rule ignores costs."
      ]
    },
    {
      "id": "H3",
      "signal": "momentum",
      "lookback": 3,
      "citation": "moskowitz-ooi-pedersen-2012",
      "hypothesis": "A three-interval lagged return ranks next-interval returns positively.",
      "mechanism": "Under-reaction followed by delayed over-reaction lets trends persist over several intervals.",
      "assumptions": [
        "Trend persistence over three intervals is visible in the cross-section."
      ],
      "limitations": [
        "Overlaps with H1 on the same panel; counting both inflates the number of tests."
      ]
    },
    {
      "id": "H4",
      "signal": "reversal",
      "lookback": 5,
      "citation": "lehmann-1990",
      "hypothesis": "Assets that fell most over the last five intervals outperform over the next interval.",
      "mechanism": "Weekly overreaction reverses once temporary price pressure fades.",
      "assumptions": [
        "Five daily intervals approximate the weekly formation period in the note."
      ],
      "limitations": [
        "Bid-ask bounce is not modelled; the note names it as a competing explanation."
      ]
    },
    {
      "id": "H5",
      "signal": "momentum",
      "lookback": 2,
      "citation": "asness-moskowitz-pedersen-2013",
      "hypothesis": "A two-interval lagged return ranks next-interval returns positively.",
      "mechanism": "Momentum appears across asset classes.",
      "assumptions": [
        "The effect generalises to this panel."
      ],
      "limitations": [
        "Cites a paper that was not among the retrieved notes."
      ]
    }
  ]
